#define CL_TARGET_OPENCL_VERSION 120
#include <CL/cl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(c) do{cl_int err=(c);if(err){fprintf(stderr,"%s: %d\n",#c,err);return 2;}}while(0)
int main(int argc,char**argv){cl_platform_id p;cl_device_id d;cl_uint count;cl_int e;CHECK(clGetPlatformIDs(1,&p,&count));CHECK(clGetDeviceIDs(p,CL_DEVICE_TYPE_GPU,1,&d,&count));cl_context ctx=clCreateContext(NULL,1,&d,NULL,NULL,&e);CHECK(e);cl_command_queue q=clCreateCommandQueue(ctx,d,0,&e);CHECK(e);
const char*src="inline __attribute__((always_inline)) uint2 divmod(uint n,uint d){uint q=0,r=0;for(int b=31;b>=0;--b){uint carry=r>>31;r=(r<<1)|((n>>b)&1u);uint take=carry | (r>=d);r-=d*take;q|=take<<b;}return (uint2)(q,r);} __kernel void coords(__global const uchar*x,uint xo,uint n,__global const int*p,__global const int*o,uint shift,__global uint2*y,uint size0,uint size1){uint g=get_global_id(0);if(g>=n || x[xo+g]==0)return;uint row=o[g>>shift]+p[g],rem=g;uint2 qr1=divmod(rem,size1);uint2 v1=(uint2)(0,0);v1.s0=qr1.y;y[row*2+1]=v1;rem=qr1.x;uint2 qr0=divmod(rem,size0);uint2 v0=(uint2)(0,0);v0.s0=qr0.y;y[row*2]=v0;}";
cl_program pr=clCreateProgramWithSource(ctx,1,&src,NULL,&e);CHECK(e);CHECK(clBuildProgram(pr,1,&d,"",NULL,NULL));cl_kernel k=clCreateKernel(pr,"coords",&e);CHECK(e);uint8_t mask[2688]={0};uint32_t positions[]={459,460,491,1125,1126,1141,1142,1143,1157,1158,2644,2645,2651,2652,2653,2654,2659,2661,2662,2669};for(int i=0;i<20;i++)mask[positions[i]]=1;int prefix[2688],offsets[21],sum=0;for(int i=0;i<2688;i++){if(i%128==0){offsets[i/128]=sum;}prefix[i]=sum-offsets[i/128];sum+=mask[i]!=0;}uint32_t poison[80],out[80];for(int i=0;i<80;i++)poison[i]=0xdeadbeef;
for(int trial=0;trial<2000;trial++){cl_mem x=clCreateBuffer(ctx,CL_MEM_READ_WRITE|CL_MEM_COPY_HOST_PTR,sizeof(mask),mask,&e);CHECK(e);cl_mem pfx=clCreateBuffer(ctx,CL_MEM_READ_WRITE|CL_MEM_COPY_HOST_PTR,sizeof(prefix),prefix,&e);CHECK(e);cl_mem off=clCreateBuffer(ctx,CL_MEM_READ_WRITE|CL_MEM_COPY_HOST_PTR,sizeof(offsets),offsets,&e);CHECK(e);cl_mem y=clCreateBuffer(ctx,CL_MEM_READ_WRITE|CL_MEM_COPY_HOST_PTR,sizeof(poison),poison,&e);CHECK(e);uint32_t zero=0,n=2688,shift=7,s0=2,s1=1344;CHECK(clSetKernelArg(k,0,sizeof(x),&x));CHECK(clSetKernelArg(k,1,4,&zero));CHECK(clSetKernelArg(k,2,4,&n));CHECK(clSetKernelArg(k,3,sizeof(pfx),&pfx));CHECK(clSetKernelArg(k,4,sizeof(off),&off));CHECK(clSetKernelArg(k,5,4,&shift));CHECK(clSetKernelArg(k,6,sizeof(y),&y));CHECK(clSetKernelArg(k,7,4,&s0));CHECK(clSetKernelArg(k,8,4,&s1));size_t global=2688,local=argc>1?strtoul(argv[1],0,10):64;CHECK(clEnqueueNDRangeKernel(q,k,1,NULL,&global,&local,0,NULL,NULL));CHECK(clFinish(q));CHECK(clEnqueueReadBuffer(q,y,CL_TRUE,0,sizeof(out),out,0,NULL,NULL));int bad=0;for(int i=0;i<20;i++)for(int j=0;j<4;j++){uint32_t expected=j==0?positions[i]/1344:j==2?positions[i]%1344:0;if(out[4*i+j]!=expected){printf("BAD trial%d row%d word%d expected%u actual%u\n",trial,i,j,expected,out[4*i+j]);bad++;}}if(bad){CHECK(clEnqueueReadBuffer(q,y,CL_TRUE,0,sizeof(out),out,0,NULL,NULL));printf("REREAD row3 %u %u %u %u\n",out[12],out[13],out[14],out[15]);return 1;}clReleaseMemObject(x);clReleaseMemObject(pfx);clReleaseMemObject(off);clReleaseMemObject(y);if(trial%25==0)printf("PASS %d\n",trial);fflush(stdout);}puts("PASS2000");return 0;}
